import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalTestCases = 1; // Only one input case expected
        for (int _ = 0; _ < totalTestCases; _++) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            int[] v = new int[10];
            for (int i=0; i<k; i++) {
                v[scanner.nextInt()] = 1;
            }
            int[] currentPoly = {1};
            int exp = n / 2;
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    currentPoly = polyConv(currentPoly, v, 998244353);
                }
                v = polyConv(v, v, 998244353);
                exp >>= 1;
            }
            long answer = 0;
            for (int val : currentPoly) {
                answer = (answer + (long) val * val) % 998244353;
            }
            System.out.println(answer);
        }
    }

    static int[] polyConv(int[] a, int[] b, int mod) {
        int size = Math.max(2, Integer.highestOneBit(a.length + b.length - 1) << 1);
        double[] A = new double[size];
        double[] B = new double[size];
        for (int i=0; i<a.length; i++) {
            int x = ((a[i] % mod) + mod) % mod;
            A[i] = x & ((1 << 15) - 1);
            A[i] += (x >> 15) * 1e-6;
        }
        for (int i=0; i<b.length; i++) {
            int x = ((b[i] % mod) + mod) % mod;
            B[i] = x & ((1 << 15) - 1);
            B[i] += (x >> 15) * 1e-6;
        }
        fftRealImag(A, B, false);
        double[] FA = new double[size];
        double[] FB = new double[size];
        for (int i=0; i<size; i++) {
            int j= (size - i) & (size - 1);
            double a1r= (A[i] + A[j]) * 0.5;
            double a1i= (A[i] - A[j]) * 0.5;
            double b1r= (B[i]+B[j]) * 0.5;
            double b1i= (B[i] - B[j]) * 0.5;
            FA[i]= a1r * b1r - a1i * b1i;
            FB[i]= a1r * b1i + a1i * b1r;
        }
        fftRealImag(FA, FB, true);
        int[] result= new int[a.length + b.length -1];
        for (int i=0; i< result.length; i++) {
            long aa= Math.round(FA[i]);
            long bb= Math.round(FB[i]);
            long val = (aa + ((bb % mod)<<15)) % mod;
            result[i]= (int) val;
        }
        return result;
    }

    static void fftRealImag(double[] a, double[] b, boolean invert) {
        int n= a.length;
        for (int i=1, j=0; i<n; i++) {
            int bitMask= n>>1;
            for (; (j & bitMask)!=0; bitMask>>=1) {
                j&= ~bitMask;
            }
            j|= bitMask;
            if (i<j) {
                double tmp= a[i];
                a[i]= a[j];
                a[j]= tmp;
                tmp= b[i];
                b[i]= b[j];
                b[j]= tmp;
            }
        }
        for (int len=2; len<=n; len<<=1) {
            double angle= 2*Math.PI/len * (invert ? -1:1);
            double c= Math.cos(angle);
            double s= Math.sin(angle);
            for (int i=0; i<n; i+=len) {
                double wReal=1, wImag=0;
                for (int j=0; j<len/2; j++) {
                    double u= a[i+j], v= a[i+j+len/2]*wReal + b[i+j+len/2]*wImag;
                    a[i+j]= u+v;
                    a[i+j+len/2]= u-v;
                    double tempWReal= wReal * c - wImag * s;
                    wImag= wImag * c + wReal * s;
                    wReal= tempWReal;
                }
            }
        }
        if (invert) {
            for (int i=0; i<n; i++) {
                a[i] /= n;
                b[i] /= n;
            }
        }
    }
}
